9	// V2: Core. Publishes commission earned/reversed notifications to affiliates when ledger entries are created or status changes.
10	class CommissionLedgerEntryObserver
11	{
12	    public bool $afterCommit = true;
13	
14	    public function __construct(private readonly NotificationPublisher $publisher) {}
15	
16	    public function created(CommissionLedgerEntry $entry): void
17	    {
18	        try {
19	            if ($entry->status !== 'approved') {
20	                return;
21	            }
22	
23	            $this->notifyEarned($entry);
24	            $this->notifyBrandSale($entry);
25	        } catch (\Throwable $e) {
26	            Log::warning('CommissionLedgerEntry created notification failed', [
27	                'entry_id' => $entry->id,
28	                'message' => $e->getMessage(),
29	            ]);
30	        }
31	    }
32	
33	    public function updated(CommissionLedgerEntry $entry): void
34	    {
35	        try {
36	            if (! $entry->isDirty('status')) {
37	                return;
38	            }
39	
40	            if ($entry->status === 'approved' && $entry->getOriginal('status') !== 'approved') {
41	                $this->notifyEarned($entry);
42	
43	                return;
44	            }
45	
46	            if ($entry->status === 'reversed') {
47	                $this->notifyReversed($entry);
48	
49	                return;
50	            }
51	
52	            if ($entry->status === 'voided') {
53	                $this->notifyVoided($entry);
54	            }
55	        } catch (\Throwable $e) {
56	            Log::warning('CommissionLedgerEntry updated notification failed', [
57	                'entry_id' => $entry->id,
