67	            return;
68	        }
69	
70	        $amount = $this->formatMoney((int) ($entry->amount_cents ?? 0), (string) ($entry->currency_code ?? 'AUD'));
71	
72	        $this->publisher->publish(
73	            professionalId: $affiliateId,
74	            frontendType: 'Success',
75	            category: 'commissions',
76	            title: 'Commission earned',
77	            body: "You earned {$amount} in commission.",
