72	        $this->publisher->publish(
73	            professionalId: $affiliateId,
74	            frontendType: 'Success',
75	            category: 'commissions',
76	            title: 'Commission earned',
77	            body: "You earned {$amount} in commission.",
78	            dedupeKey: "commission.earned.{$entry->id}",
79	            ctaUrl: '/account/store?section=analytics',
80	            retentionConfigKey: 'commission',
81	        );
82	    }
83	
84	    private function notifyReversed(CommissionLedgerEntry $entry): void
85	    {
86	        $affiliateId = trim((string) ($entry->affiliate_professional_id ?? ''));
87	        if ($affiliateId === '') {
88	            return;
89	        }
90	
91	        $amount = $this->formatMoney((int) ($entry->amount_cents ?? 0), (string) ($entry->currency_code ?? 'AUD'));
92	
93	        $this->publisher->publish(
