122	            retentionConfigKey: 'commission',
123	        );
124	    }
125	
126	    // V2: Notifies the brand when an affiliate sale generates commission.
127	    private function notifyBrandSale(CommissionLedgerEntry $entry): void
128	    {
129	        $brandId = trim((string) ($entry->brand_professional_id ?? ''));
130	        if ($brandId === '') {
131	            return;
132	        }
133	
134	        $amount = $this->formatMoney((int) ($entry->amount_cents ?? 0), (string) ($entry->currency_code ?? 'AUD'));
135	        $affiliateName = $entry->affiliateProfessional?->display_name ?? 'An affiliate';
136	
137	        $this->publisher->publish(
138	            professionalId: $brandId,
